INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (10118, 1, 7, 91002, "フリーマーケット会場", "ペコリーヌとの出会い", "フリーマーケットを訪れたジータが出会ったのは\n城をこっそり抜け出していたペコリーヌだった。", 0, 2, 20063115, 5118061, 2834, 40, 8, "青空の下で謁見");
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (10118, 1, 7, 91002, "フリーマーケット会場", "マホとの出会い", "ジータたちがフリーマーケットを巡っていると\n露店を出していたマホに声をかけられる。", 0, 2, 20063115, 5118062, 2835, 40, 8, "未来の騎空団\nマスコット？");
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (10118, 1, 7, 91002, "ランドソル市街地", "アキノとの出会い", "ジータが騎空団への依頼を確認していると、\n高笑いをしながらアキノが現れる。", 0, 2, 20063115, 5118063, 2837, 40, 8, "お嬢さまからの\n緊急依頼");
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (10118, 1, 18, 91002, "フリーマーケット会場", "ジュンとの出会い", "ジータたちは、フリーマーケット会場で\n少し困った様子のジュンを見かける。", 0, 2, 20063115, 5118064, 4108402, 40, 8, "黄金色の悩みごと");
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (10118, 1, 18, 91002, "フリーマーケット会場", "カオリとの出会い", "フリーマーケットの隅で開かれる格闘大会──\nそこにはカオリもいて……？", 0, 2, 20063115, 5118065, 4107402, 40, 8, "白熱！　格闘大会！");
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (10118, 1, 16, 91002, "オーエド町", "ニノンとの出会い", "太鼓祭を控えるオーエド町──\nジータは、困った様子のニノンと出会う。", 1, 2, 20063115, 5118066, 9000227, 40, 8, "祭り太鼓はオーエドの華");
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (10118, 1, 19, 91002, "フリーマーケット会場", "スズナとの出会い", "ビカラはイベントに出演中のスズナを見かける。\nしかし、スズナはどこか困っているようで……？", 0, 3, 20063115, 5118067, 2101181, 40, 8, "人気者は遅れて\nやってくる");
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (10118, 1, 18, 91002, "ランドソル市街地", "ナナカとの出会い", "ビカラたちが街を散策していると、通りかかった\nナナカが興奮した様子で近づいてきて……？", 0, 3, 20063115, 5118068, 4109402, 40, 8, "巫女・ミーツ・魔法少女");
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (10118, 1, 18, 91002, "フリーマーケット会場", "キャル＆コッコロとの出会い", "ネズ耳をなくしてしまい絶望するビカラ。同じ頃\nキャルとコッコロは落とし物を拾っており……", 0, 3, 20063115, 5118069, 4305402, 40, 8, "ネズ耳は二度なくなる");
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (10118, 1, 18, 91002, "ランドソル市街地", "ユカリとの出会い", "街外れでひと休みをしていたビカラたちは、\nすっかりゴキゲンな様子のユカリと出会う。", 0, 3, 20063115, 5118070, 4101402, 40, 8, "この出会いにカンパイ！");
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (10118, 1, 18, 91002, "ランドソル市街地", "アオイとの出会い", "ビカラは、人混みに怯えるアオイを心配し、\n陽気に声をかけるも……", 0, 3, 20063115, 5118071, 4106402, 40, 8, "陰陽アンサンブル");
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (10118, 1, 7, 91002, "フリーマーケット会場", "シノブとの出会い", "ビカラがフリーマーケット会場を歩いていると\n占いをしていたシノブに声をかけられる。", 1, 3, 20063115, 5118072, 2836, 40, 8, "運試し十番勝負！");
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (10118, 0, 0, 0, 0, "オープニング", 0, 0, 1, 20063115, 5118600, 0, 0, 0, "彼女たちの新たな日常");
